const configRows = $('Buscar Config').all().map(i => i.json);
const config = {};
configRows.forEach(r => { config[r.chave] = r.valor; });

const metaDia = parseFloat(config.meta_visitas_dia) || 12;
const metaMes = parseFloat(config.meta_visitas_mes) || 280;
const slaDias = parseFloat(config.sla_dias_padrao) || 3;
const emailsCsv = config.emails_relatorio || '';
const emailList = emailsCsv.split(',').map(s => s.trim()).filter(Boolean);

const usuariosCampo = $('Buscar Usuarios Campo').all().map(i => i.json);
// meta efetiva: individual (usuarios.meta_visitas_dia) com fallback na config
const metaDoUsuario = (u) => (u && u.meta_visitas_dia != null ? parseFloat(u.meta_visitas_dia) : metaDia);
const gerenteRows = $('Buscar Gerente').all().map(i => i.json);
const gerente = gerenteRows[0] || {};

const agendaHoje = $('Buscar Agenda Hoje').all().map(i => i.json);
const visitasPlanejadas = agendaHoje.length;
const visitasRealizadas = agendaHoje.filter(a => a.status === 'realizada').length;

const porUsuario = {};
usuariosCampo.forEach(u => {
  porUsuario[u.id] = { nome: u.nome, meta: metaDoUsuario(u), planejadas: 0, realizadas: 0 };
});
// agenda de quem nao esta no roster (usuario removido/inativo, ou linha sem responsavel)
agendaHoje.forEach(a => {
  const chave = a.usuario_id || 'sem_responsavel';
  if (!porUsuario[chave]) {
    porUsuario[chave] = {
      nome: a.usuario_id ? a.usuario_id : 'sem responsavel',
      meta: metaDia, planejadas: 0, realizadas: 0
    };
  }
  porUsuario[chave].planejadas += 1;
  if (a.status === 'realizada') porUsuario[chave].realizadas += 1;
});

// so entra no ranking quem tinha rota hoje ou registrou visita:
// quem nao tem visita planejada nao aparece como abaixo da meta.
const rankingUsuarios = Object.values(porUsuario)
  .filter(u => u.planejadas > 0 || u.realizadas > 0)
  .sort((a, b) => (b.realizadas - a.realizadas) || a.nome.localeCompare(b.nome));

// meta do dia da equipe = soma das metas efetivas de quem tinha rota hoje
const metaDiaEquipe = rankingUsuarios.reduce((acc, u) => acc + u.meta, 0);
const pctMetaDia = metaDiaEquipe > 0 ? Math.round((visitasRealizadas / metaDiaEquipe) * 1000) / 10 : 0;

const detalhePorUsuario = rankingUsuarios.map((u, idx) => {
  const pct = u.meta > 0 ? Math.round((u.realizadas / u.meta) * 1000) / 10 : 0;
  return { posicao: idx + 1, nome: u.nome, realizadas: u.realizadas, planejadas: u.planejadas, meta: u.meta, pctMeta: pct };
});

const agendaMes = $('Buscar Agenda Mes').all().map(i => i.json);
const acumuladoMes = agendaMes.length;
const pctMetaMes = metaMes > 0 ? Math.round((acumuladoMes / metaMes) * 1000) / 10 : 0;

const suspeitosRows = $('Buscar Checkins Suspeitos').all().map(i => i.json);
const suspeitosCount = suspeitosRows.length;

const opRows = $('Buscar Oportunidades Hoje').all().map(i => i.json);
const oportunidadesCount = opRows.length;
const oportunidadesPorProduto = {};
opRows.forEach(o => {
  const p = o.produto || 'nao_informado';
  oportunidadesPorProduto[p] = (oportunidadesPorProduto[p] || 0) + 1;
});

const perdasRows = $('Buscar Perdas Hoje').all().map(i => i.json);
const perdasCount = perdasRows.length;

const contratosRows = $('Buscar Contratos Abertos').all().map(i => i.json);
const agora = Date.now();
const contratosComDias = contratosRows.map(c => {
  const desde = c.etapa_desde ? new Date(c.etapa_desde).getTime() : agora;
  const diasParado = Math.floor((agora - desde) / (1000 * 60 * 60 * 24));
  return Object.assign({}, c, { diasParado: diasParado, atrasado: diasParado > slaDias });
});
const contratosAtrasados = contratosComDias.filter(c => c.atrasado);
const contratosAtrasadosCount = contratosAtrasados.length;

const retornosRows = $('Buscar Retornos Vencidos').all().map(i => i.json);
const retornosVencidosCount = retornosRows.length;

const now = new Date();
const dd = String(now.getDate()).padStart(2, '0');
const mm = String(now.getMonth() + 1).padStart(2, '0');
const yyyy = now.getFullYear();
const dataFormatada = dd + '/' + mm;
const dataCompleta = dd + '/' + mm + '/' + yyyy;

const oportunidadesLinhas = Object.keys(oportunidadesPorProduto).length
  ? Object.entries(oportunidadesPorProduto).map(function (e) { return '<li>' + e[0] + ': ' + e[1] + '</li>'; }).join('')
  : '<li>nenhuma</li>';

const perdasLinhas = perdasRows.length
  ? perdasRows.map(function (p) { return '<li>Loja ' + (p.loja_id || '-') + ' - motivo: ' + (p.motivo_nao_fechamento || 'nao informado') + '</li>'; }).join('')
  : '<li>nenhuma</li>';

const contratosLinhas = contratosAtrasados.length
  ? contratosAtrasados.map(function (c) { return '<li>Contrato ' + (c.numero_fluig || c.id) + ' - etapa: ' + c.etapa + ' - ' + c.diasParado + ' dias parado</li>'; }).join('')
  : '<li>nenhum</li>';

const retornosLinhas = retornosRows.length
  ? retornosRows.map(function (r) { return '<li>Loja ' + (r.loja_id || '-') + ' - agendado para ' + r.data + '</li>'; }).join('')
  : '<li>nenhum</li>';

const detalhePorUsuarioLinhas = detalhePorUsuario.length
  ? detalhePorUsuario.map(function (u) { return '<li>' + u.posicao + '. ' + u.nome + ': ' + u.realizadas + '/' + u.planejadas + ' realizadas - ' + u.pctMeta + '% da meta de ' + u.meta + '</li>'; }).join('')
  : '<li>ninguem com rota hoje</li>';

const htmlBody = '<h2>Relatorio Diario Rota Viva - ' + dataCompleta + '</h2>' +
  '<h3>Visitas de hoje</h3>' +
  '<p>Realizadas: ' + visitasRealizadas + ' | Planejadas: ' + visitasPlanejadas + ' | % da meta do dia: ' + pctMetaDia + '%</p>' +
  '<h4>Ranking do dia</h4><ul>' + detalhePorUsuarioLinhas + '</ul>' +
  '<h3>Acumulado do mes</h3>' +
  '<p>' + acumuladoMes + ' de ' + metaMes + ' (' + pctMetaMes + '%)</p>' +
  '<h3>Check-ins suspeitos hoje</h3>' +
  '<p>' + suspeitosCount + '</p>' +
  '<h3>Oportunidades novas hoje</h3>' +
  '<ul>' + oportunidadesLinhas + '</ul>' +
  '<h3>Perdas do dia (sem interesse)</h3>' +
  '<ul>' + perdasLinhas + '</ul>' +
  '<h3>Contratos parados alem do SLA (' + slaDias + ' dias)</h3>' +
  '<ul>' + contratosLinhas + '</ul>' +
  '<h3>Retornos vencidos nao cumpridos</h3>' +
  '<ul>' + retornosLinhas + '</ul>';

return [{
  json: {
    dataFormatada: dataFormatada,
    dataCompleta: dataCompleta,
    visitasRealizadas: visitasRealizadas,
    visitasPlanejadas: visitasPlanejadas,
    metaDiaEquipe: metaDiaEquipe,
    ranking: detalhePorUsuario,
    pctMetaDia: pctMetaDia,
    acumuladoMes: acumuladoMes,
    metaMes: metaMes,
    pctMetaMes: pctMetaMes,
    suspeitosCount: suspeitosCount,
    oportunidadesCount: oportunidadesCount,
    oportunidadesPorProduto: oportunidadesPorProduto,
    perdasCount: perdasCount,
    contratosAtrasadosCount: contratosAtrasadosCount,
    retornosVencidosCount: retornosVencidosCount,
    gerenteNome: gerente.nome || 'Gerente',
    gerenteTelefone: gerente.telefone || '',
    emailsRelatorioStr: emailList.join(','),
    htmlBody: htmlBody
  }
}];
